{"command": "python -c "
import sqlparse
from sqlparse import sql, tokens as T
for q in [\"a LIKE 'x'\", \"a ILIKE 'x'\", \"a NOT LIKE 'x'\", \"a RLIKE 'x'\"]:
    p = sqlparse.parse(q)[0]
    print(q, '->', p.tokens)
    for t in p.tokens:
        print('  ', type(t), t.ttype, repr(str(t)))
"
"}

